<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';$db=db();$token=preg_replace('/[^a-f0-9]/','',strtolower((string)($_GET['token']??'')));$s=$db->prepare('SELECT i.*,COALESCE(c.name,l.name) client_name,COALESCE(c.company,l.company) company,COALESCE(c.email,l.email) email FROM invoices i LEFT JOIN clients c ON c.id=i.client_id LEFT JOIN leads l ON l.id=i.lead_id WHERE i.public_token=? LIMIT 1');$s->execute([$token]);$i=$s->fetch();if(!$i){http_response_code(404);exit('Invoice not found.');}$s=$db->prepare('SELECT * FROM invoice_items WHERE invoice_id=? ORDER BY sort_order,id');$s->execute([$i['id']]);$items=$s->fetchAll();$e=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');function m4($v,$c){return $c.' '.number_format((float)$v,2);} ?><!doctype html><html><head><meta charset="utf-8"><title><?=$e($i['invoice_number'])?></title><style>@page{size:A4;margin:18mm}body{font-family:Arial,sans-serif;color:#202124;font-size:12px}.top{display:flex;justify-content:space-between;border-bottom:2px solid #222;padding-bottom:15px}.muted{color:#666}.title{margin:28px 0 8px;font-size:25px}.table{width:100%;border-collapse:collapse;margin-top:20px}.table th,.table td{padding:9px;border-bottom:1px solid #ddd}.table th{background:#f3f4f6;text-align:left}.num{text-align:right}.total{font-weight:bold;font-size:16px}.section{margin-top:24px}.actions{margin-top:25px}.btn{display:inline-block;padding:9px 14px;background:#222;color:#fff;text-decoration:none}@media print{.actions{display:none}}</style></head><body><div class="top"><div><h1>Distinguished Web Services</h1><div class="muted">Invoice</div></div><div class="num"><strong><?=$e($i['invoice_number'])?></strong><br>Issued <?=$e($i['issue_date'])?><br>Due <?=$e($i['due_date']?:'—')?></div></div><h2 class="title"><?=$e($i['title'])?></h2><p>Bill to <strong><?=$e($i['client_name'])?></strong><?php if($i['company']):?> — <?=$e($i['company'])?><?php endif;?><br><?=$e($i['email'])?></p><table class="table"><thead><tr><th>Description</th><th class="num">Qty</th><th class="num">Unit</th><th class="num">Amount</th></tr></thead><tbody><?php foreach($items as $x):?><tr><td><?=$e($x['description'])?></td><td class="num"><?=$e($x['quantity'])?></td><td class="num"><?=m4($x['unit_price'],$i['currency'])?></td><td class="num"><?=m4($x['amount']??$x['line_total'],$i['currency'])?></td></tr><?php endforeach;?></tbody><tfoot><tr><td colspan="3" class="num">Subtotal</td><td class="num"><?=m4($i['subtotal'],$i['currency'])?></td></tr><tr><td colspan="3" class="num">Discount</td><td class="num">- <?=m4($i['discount'],$i['currency'])?></td></tr><tr><td colspan="3" class="num">Tax</td><td class="num"><?=m4($i['tax']??$i['tax_amount'],$i['currency'])?></td></tr><tr><td colspan="3" class="num total">Total</td><td class="num total"><?=m4($i['total'],$i['currency'])?></td></tr><tr><td colspan="3" class="num">Amount Paid</td><td class="num"><?=m4($i['amount_paid'],$i['currency'])?></td></tr><tr><td colspan="3" class="num total">Balance Due</td><td class="num total"><?=m4($i['balance_due'],$i['currency'])?></td></tr></tfoot></table><?php if($i['notes']):?><div class="section"><strong>Notes</strong><p><?=nl2br($e($i['notes']))?></p></div><?php endif;?><?php if($i['terms']):?><div class="section"><strong>Terms &amp; Conditions</strong><p><?=nl2br($e($i['terms']))?></p></div><?php endif;?><div class="actions"><a class="btn" href="#" onclick="window.print();return false">Print / Save as PDF</a></div></body></html>